// src/pages/business/LoyaltyPage.tsx
import React, { useEffect, useState } from "react";
import TabBar from "../../components/common/TabBar";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";
import api from "../../utils/api";

const LoyaltyPage: React.FC = () => {
  // TODO: replace with however you store the logged-in business ID
  const businessId = localStorage.getItem("businessId");

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [form, setForm] = useState({
    enabled: false,
    type: "points",
    pointsPerBooking: 1,
    rewardThreshold: 10,
    rewardDescription: "",
    expiryMonths: 0,
  });

  useEffect(() => {
    const fetchLoyalty = async () => {
      try {
        setLoading(true);
        setError("");
        const res = await api.get(`/business/${businessId}/loyalty`);
        if (res.data) {
          setForm((prev) => ({
            ...prev,
            ...res.data,
          }));
        }
      } catch (err) {
        console.error(err);
        setError("Failed to load loyalty settings.");
      } finally {
        setLoading(false);
      }
    };

    if (businessId) {
      fetchLoyalty();
    } else {
      setLoading(false);
      setError("No businessId found. (Check auth / localStorage)");
    }
  }, [businessId]);

  const handleChange = (field: string, value: any) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    setError("");
    setSuccess("");
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!businessId) return;

    try {
      setSaving(true);
      setError("");
      setSuccess("");

      const payload = {
        ...form,
        pointsPerBooking: Number(form.pointsPerBooking),
        rewardThreshold: Number(form.rewardThreshold),
        expiryMonths: Number(form.expiryMonths),
      };

      const res = await api.put(`/business/${businessId}/loyalty`, payload);
      setForm((prev) => ({ ...prev, ...res.data }));
      setSuccess("Loyalty settings saved.");
    } catch (err) {
      console.error(err);
      setError("Failed to save loyalty settings.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="business-page">
      <TabBar type="business" />

      <div className="page-content">
        <h1 className="page-title">Loyalty Program</h1>

        {loading ? (
          <p>Loading...</p>
        ) : (
          <form onSubmit={handleSubmit} className="loyalty-form">
            <div className="form-section">
              <label className="checkbox-row">
                <input
                  type="checkbox"
                  checked={form.enabled}
                  onChange={(e) => handleChange("enabled", e.target.checked)}
                />
                <span>Enable loyalty program</span>
              </label>
            </div>

            <div className="form-section">
              <label>Program type</label>
              <div className="radio-row">
                <label>
                  <input
                    type="radio"
                    name="type"
                    value="points"
                    checked={form.type === "points"}
                    onChange={(e) => handleChange("type", e.target.value)}
                  />
                  Points
                </label>
                <label>
                  <input
                    type="radio"
                    name="type"
                    value="stamps"
                    checked={form.type === "stamps"}
                    onChange={(e) => handleChange("type", e.target.value)}
                  />
                  Stamps / Visits
                </label>
              </div>
            </div>

            <div className="form-section">
              <TextBox
                label={
                  form.type === "points"
                    ? "Points per completed booking"
                    : "Stamps per completed booking"
                }
                type="number"
                min="0"
                value={form.pointsPerBooking}
                onChange={(e) =>
                  handleChange("pointsPerBooking", e.target.value)
                }
              />
            </div>

            <div className="form-section">
              <TextBox
                label={
                  form.type === "points"
                    ? "Points needed for reward"
                    : "Stamps needed for reward"
                }
                type="number"
                min="1"
                value={form.rewardThreshold}
                onChange={(e) =>
                  handleChange("rewardThreshold", e.target.value)
                }
              />
            </div>

            <div className="form-section">
              <TextBox
                label="Reward description (e.g. 'Free blow-dry', '20% off next visit')"
                type="text"
                value={form.rewardDescription}
                onChange={(e) =>
                  handleChange("rewardDescription", e.target.value)
                }
              />
            </div>

            <div className="form-section">
              <TextBox
                label="Expiry (months) - 0 means rewards never expire"
                type="number"
                min="0"
                value={form.expiryMonths}
                onChange={(e) => handleChange("expiryMonths", e.target.value)}
              />
            </div>

            {error && <p className="error-text">{error}</p>}
            {success && <p className="success-text">{success}</p>}

            <Button type="submit" disabled={saving}>
              {saving ? "Saving..." : "Save loyalty settings"}
            </Button>
          </form>
        )}
      </div>
    </div>
  );
};

export default LoyaltyPage;
